SELECT c."text"
FROM "comments" c
WHERE c."userdisplayname" = 'Harvey Motulsky';

SELECT COUNT(*) AS total_comments
FROM "comments" c
WHERE c."userid" = 13;

SELECT
  (SELECT COUNT(*) FROM "posts" p WHERE p."owneruserid" = 24)::NUMERIC
  / NULLIF((SELECT COUNT(*) FROM "votes" v WHERE v."userid" = 24), 0) AS posts_to_votes_ratio;

SELECT p."viewcount"
FROM "posts" p
WHERE p."title" = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer';

SELECT COUNT(*) AS total_superheroes_without_full_name
FROM "superhero" s
WHERE s."full_name" IS NULL;

SELECT
  (SELECT "s"."weight_kg" FROM "superhero" "s" WHERE "s"."full_name" = 'Emil Blonsky') -
  (SELECT "s"."weight_kg" FROM "superhero" "s" WHERE "s"."full_name" = 'Charles Chandler') AS difference;

SELECT COUNT(DISTINCT m."member_id") AS student_count
FROM "member" m
WHERE LOWER(m."position") LIKE '%president%';
